import binascii
from quicFunctions import *

# captured_packet = binascii.unhexlify("")
captured_packet= binascii.unhexlify("")
dcid = binascii.unhexlify("f234c00c2ca33167")
print("Destination Connection ID: ", binascii.hexlify(dcid))


keys = KeyDerivation.derive_keys(KeyDerivation, dcid, "server")
# Print the values of the keys
print("Initial Secret       :", binascii.hexlify(keys.initial_secret))
print("Client Initial Secret:", binascii.hexlify(keys.client_initial_secret))
print("Server Initial Secret:", binascii.hexlify(keys.server_initial_secret))
print("Key                  :", binascii.hexlify(keys.key))
print("IV                   :", binascii.hexlify(keys.iv))
print("HP                   :", binascii.hexlify(keys.hp))


demasked_header, protected_payload = Decrypt.headerUnmask(captured_packet, keys.hp)
print("Protected Payload: ", binascii.hexlify(protected_payload))
print("Decrypted Header: ", binascii.hexlify(demasked_header))
decrypted_payload = Decrypt.aead_decrypt(keys.key, keys.iv, protected_payload, demasked_header)
print("Decrypted Payload: ", binascii.hexlify(decrypted_payload))
print("Size of Decrypted Payload: ", len(decrypted_payload))
print("Size of captured packet: ", len(captured_packet))

